-- Client and Project Management System for CogniVectra
-- Complete CRM and project tracking solution

-- =============================================
-- 1. CLIENTS TABLE
-- =============================================
CREATE TABLE IF NOT EXISTS public.clients (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
  updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
  
  -- Client ID (auto-generated)
  client_id text UNIQUE, -- e.g., CL001, CL002
  
  -- Company Information
  company_name text NOT NULL,
  industry text,
  company_size text CHECK (company_size IN ('startup', '1-10', '11-50', '51-200', '201-500', '500+')),
  website text,
  
  -- Primary Contact
  primary_contact_name text NOT NULL,
  primary_contact_email text NOT NULL,
  primary_contact_phone text,
  primary_contact_title text,
  
  -- Additional Contacts (JSON array)
  additional_contacts jsonb DEFAULT '[]'::jsonb,
  
  -- Address
  address_line1 text,
  address_line2 text,
  city text,
  state text,
  country text DEFAULT 'India',
  pincode text,
  
  -- Business Details
  client_type text DEFAULT 'prospect' CHECK (client_type IN ('prospect', 'lead', 'active', 'inactive', 'churned')),
  lead_source text, -- e.g., 'website', 'referral', 'linkedin', 'cold outreach'
  
  -- Engagement
  services_interested text[], -- Array of services
  budget_range text,
  timeline text,
  
  -- Contract & Billing
  contract_type text CHECK (contract_type IN ('hourly', 'fixed', 'retainer', 'equity')),
  billing_cycle text CHECK (billing_cycle IN ('weekly', 'bi-weekly', 'monthly', 'milestone', 'one-time')),
  payment_terms text, -- e.g., 'Net 30', 'Net 15', '50% upfront'
  
  -- Financial
  total_revenue numeric(12, 2) DEFAULT 0,
  outstanding_balance numeric(12, 2) DEFAULT 0,
  
  -- Relationship
  account_manager_id bigint REFERENCES public.employees(id),
  relationship_status text DEFAULT 'new' CHECK (relationship_status IN ('new', 'nurturing', 'engaged', 'at_risk', 'healthy', 'champion')),
  
  -- Dates
  first_contact_date date,
  onboarding_completed_date date,
  last_interaction_date date,
  
  -- Documents
  contract_url text,
  nda_url text,
  
  -- Tags and Notes
  tags text[],
  notes text,
  
  -- Status
  is_active boolean DEFAULT true
);

-- =============================================
-- 2. PROJECTS TABLE
-- =============================================
CREATE TABLE IF NOT EXISTS public.projects (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
  updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
  
  -- Project ID (auto-generated)
  project_id text UNIQUE, -- e.g., PRJ001, PRJ002
  
  -- Basic Information
  project_name text NOT NULL,
  client_id bigint REFERENCES public.clients(id) NOT NULL,
  
  -- Project Details
  project_type text NOT NULL, -- e.g., 'Cloud Infrastructure', 'DevOps', 'SaaS Development'
  description text,
  objectives text,
  
  -- Scope
  deliverables text[],
  tech_stack text[],
  
  -- Timeline
  start_date date,
  estimated_end_date date,
  actual_end_date date,
  
  -- Status
  project_status text DEFAULT 'planning' CHECK (project_status IN (
    'planning', 'in_progress', 'on_hold', 'completed', 'cancelled', 'maintenance'
  )),
  health_status text DEFAULT 'on_track' CHECK (health_status IN (
    'on_track', 'at_risk', 'delayed', 'blocked'
  )),
  completion_percentage integer DEFAULT 0 CHECK (completion_percentage >= 0 AND completion_percentage <= 100),
  
  -- Team
  project_manager_id bigint REFERENCES public.employees(id),
  team_members jsonb DEFAULT '[]'::jsonb, -- Array of employee IDs with roles
  
  -- Financial
  project_value numeric(12, 2),
  budget numeric(12, 2),
  actual_cost numeric(12, 2) DEFAULT 0,
  billing_type text CHECK (billing_type IN ('hourly', 'fixed', 'milestone', 'retainer')),
  hourly_rate numeric(10, 2),
  
  -- Milestones (JSON array)
  milestones jsonb DEFAULT '[]'::jsonb,
  
  -- Communication
  slack_channel text,
  github_repo text,
  project_drive_url text,
  
  -- Risks and Issues
  risks text[],
  blockers text[],
  
  -- Documents
  proposal_url text,
  contract_url text,
  documentation_url text,
  
  -- Tags and Notes
  tags text[],
  notes text,
  
  -- Metadata
  priority text DEFAULT 'medium' CHECK (priority IN ('low', 'medium', 'high', 'critical')),
  is_billable boolean DEFAULT true,
  is_active boolean DEFAULT true
);

-- =============================================
-- 3. PROJECT TASKS TABLE
-- =============================================
CREATE TABLE IF NOT EXISTS public.project_tasks (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
  updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
  
  -- Task Details
  project_id bigint REFERENCES public.projects(id) NOT NULL,
  task_name text NOT NULL,
  description text,
  
  -- Assignment
  assigned_to bigint REFERENCES public.employees(id),
  
  -- Status
  task_status text DEFAULT 'todo' CHECK (task_status IN (
    'todo', 'in_progress', 'review', 'blocked', 'completed', 'cancelled'
  )),
  priority text DEFAULT 'medium' CHECK (priority IN ('low', 'medium', 'high', 'critical')),
  
  -- Timeline
  due_date date,
  completed_at timestamp with time zone,
  
  -- Effort
  estimated_hours numeric(6, 2),
  actual_hours numeric(6, 2),
  
  -- Dependencies
  depends_on bigint[], -- Array of task IDs
  
  -- Tags
  tags text[]
);

-- =============================================
-- 4. CLIENT INTERACTIONS TABLE
-- =============================================
CREATE TABLE IF NOT EXISTS public.client_interactions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
  
  -- Reference
  client_id bigint REFERENCES public.clients(id) NOT NULL,
  project_id bigint REFERENCES public.projects(id), -- Optional
  
  -- Interaction Details
  interaction_type text NOT NULL CHECK (interaction_type IN (
    'call', 'email', 'meeting', 'demo', 'proposal', 'contract', 'support', 'other'
  )),
  interaction_date timestamp with time zone DEFAULT timezone('utc'::text, now()),
  
  -- Content
  subject text,
  summary text NOT NULL,
  outcome text,
  
  -- Participants
  cognivectra_participants text[], -- Employee names
  client_participants text[], -- Client contact names
  
  -- Follow-up
  follow_up_required boolean DEFAULT false,
  follow_up_date date,
  follow_up_notes text,
  
  -- Recorded by
  recorded_by bigint REFERENCES public.employees(id)
);

-- =============================================
-- 5. INVOICES TABLE
-- =============================================
CREATE TABLE IF NOT EXISTS public.invoices (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
  updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
  
  -- Invoice ID (auto-generated)
  invoice_number text UNIQUE, -- e.g., INV-2026-001
  
  -- References
  client_id bigint REFERENCES public.clients(id) NOT NULL,
  project_id bigint REFERENCES public.projects(id),
  
  -- Invoice Details
  invoice_date date NOT NULL,
  due_date date NOT NULL,
  
  -- Line Items (JSON array)
  line_items jsonb NOT NULL, -- [{description, quantity, rate, amount}, ...]
  
  -- Amounts
  subtotal numeric(12, 2) NOT NULL,
  tax_percentage numeric(5, 2) DEFAULT 0,
  tax_amount numeric(12, 2) DEFAULT 0,
  total_amount numeric(12, 2) NOT NULL,
  
  -- Payment
  payment_status text DEFAULT 'draft' CHECK (payment_status IN (
    'draft', 'sent', 'viewed', 'partial', 'paid', 'overdue', 'cancelled'
  )),
  payment_date date,
  payment_method text,
  payment_reference text,
  
  -- Documents
  invoice_pdf_url text,
  
  -- Notes
  notes text,
  internal_notes text
);

-- =============================================
-- 6. ENABLE ROW LEVEL SECURITY
-- =============================================
ALTER TABLE public.clients ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.project_tasks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.client_interactions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.invoices ENABLE ROW LEVEL SECURITY;

