-- =============================================
-- 9. AUTO-GENERATE CLIENT ID
-- =============================================
CREATE OR REPLACE FUNCTION generate_client_id()
RETURNS TRIGGER AS $$
DECLARE
  next_id INTEGER;
  new_client_id TEXT;
BEGIN
  SELECT COALESCE(MAX(CAST(SUBSTRING(client_id FROM 3) AS INTEGER)), 0) + 1
  INTO next_id
  FROM public.clients
  WHERE client_id LIKE 'CL%';
  
  new_client_id := 'CL' || LPAD(next_id::TEXT, 3, '0');
  NEW.client_id := new_client_id;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS set_client_id ON public.clients;
CREATE TRIGGER set_client_id
  BEFORE INSERT ON public.clients
  FOR EACH ROW
  WHEN (NEW.client_id IS NULL)
  EXECUTE FUNCTION generate_client_id();

-- =============================================
-- 10. AUTO-GENERATE PROJECT ID
-- =============================================
CREATE OR REPLACE FUNCTION generate_project_id()
RETURNS TRIGGER AS $$
DECLARE
  next_id INTEGER;
  new_project_id TEXT;
BEGIN
  SELECT COALESCE(MAX(CAST(SUBSTRING(project_id FROM 4) AS INTEGER)), 0) + 1
  INTO next_id
  FROM public.projects
  WHERE project_id LIKE 'PRJ%';
  
  new_project_id := 'PRJ' || LPAD(next_id::TEXT, 3, '0');
  NEW.project_id := new_project_id;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS set_project_id ON public.projects;
CREATE TRIGGER set_project_id
  BEFORE INSERT ON public.projects
  FOR EACH ROW
  WHEN (NEW.project_id IS NULL)
  EXECUTE FUNCTION generate_project_id();

-- =============================================
-- 11. AUTO-GENERATE INVOICE NUMBER
-- =============================================
CREATE OR REPLACE FUNCTION generate_invoice_number()
RETURNS TRIGGER AS $$
DECLARE
  next_id INTEGER;
  year TEXT;
  new_invoice_number TEXT;
BEGIN
  year := TO_CHAR(CURRENT_DATE, 'YYYY');
  
  SELECT COALESCE(MAX(CAST(SUBSTRING(invoice_number FROM LENGTH(invoice_number) - 2) AS INTEGER)), 0) + 1
  INTO next_id
  FROM public.invoices
  WHERE invoice_number LIKE 'INV-' || year || '-%';
  
  new_invoice_number := 'INV-' || year || '-' || LPAD(next_id::TEXT, 3, '0');
  NEW.invoice_number := new_invoice_number;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS set_invoice_number ON public.invoices;
CREATE TRIGGER set_invoice_number
  BEFORE INSERT ON public.invoices
  FOR EACH ROW
  WHEN (NEW.invoice_number IS NULL)
  EXECUTE FUNCTION generate_invoice_number();

-- =============================================
-- 12. CREATE VIEWS FOR DASHBOARDS
-- =============================================

-- Client Summary View
DROP VIEW IF EXISTS public.client_summary;
CREATE OR REPLACE VIEW public.client_summary AS
SELECT 
  c.id,
  c.client_id,
  c.company_name,
  c.industry,
  c.client_type,
  c.relationship_status,
  c.primary_contact_name,
  c.primary_contact_email,
  c.total_revenue,
  c.outstanding_balance,
  c.is_active,
  COUNT(DISTINCT p.id) as active_projects,
  COUNT(DISTINCT i.id) as total_invoices,
  SUM(CASE WHEN i.payment_status = 'paid' THEN i.total_amount ELSE 0 END) as paid_amount,
  SUM(CASE WHEN i.payment_status IN ('sent', 'viewed', 'overdue') THEN i.total_amount ELSE 0 END) as pending_amount,
  e.full_name as account_manager_name
FROM public.clients c
LEFT JOIN public.projects p ON c.id = p.client_id AND p.is_active = true
LEFT JOIN public.invoices i ON c.id = i.client_id
LEFT JOIN public.employees e ON c.account_manager_id = e.id
GROUP BY c.id, e.full_name
ORDER BY c.created_at DESC;

-- Project Summary View
DROP VIEW IF EXISTS public.project_summary;
CREATE OR REPLACE VIEW public.project_summary AS
SELECT 
  p.id,
  p.project_id,
  p.project_name,
  p.client_id, -- Keep BIGINT client_id for foreign key operations
  p.project_type,
  p.project_status,
  p.health_status,
  p.completion_percentage,
  p.start_date,
  p.estimated_end_date,
  p.project_value,
  p.budget,
  p.actual_cost,
  c.company_name as client_name,
  c.client_id as client_code, -- Rename text client_id to client_code
  pm.full_name as project_manager_name,
  COUNT(DISTINCT pt.id) as total_tasks,
  COUNT(DISTINCT CASE WHEN pt.task_status = 'completed' THEN pt.id END) as completed_tasks,
  p.is_active
FROM public.projects p
LEFT JOIN public.clients c ON p.client_id = c.id
LEFT JOIN public.employees pm ON p.project_manager_id = pm.id
LEFT JOIN public.project_tasks pt ON p.id = pt.project_id
GROUP BY p.id, c.company_name, c.client_id, pm.full_name
ORDER BY p.created_at DESC;

-- Business Metrics View
DROP VIEW IF EXISTS public.business_metrics;
CREATE OR REPLACE VIEW public.business_metrics AS
SELECT 
  (SELECT COUNT(*) FROM public.clients WHERE is_active = true) as total_active_clients,
  (SELECT COUNT(*) FROM public.clients WHERE client_type = 'prospect') as total_prospects,
  (SELECT COUNT(*) FROM public.projects WHERE is_active = true) as total_active_projects,
  (SELECT COUNT(*) FROM public.projects WHERE project_status = 'in_progress') as projects_in_progress,
  (SELECT COUNT(*) FROM public.employees WHERE employment_status IN ('active', 'confirmed')) as total_active_employees,
  (SELECT SUM(total_revenue) FROM public.clients) as total_revenue,
  (SELECT SUM(outstanding_balance) FROM public.clients) as total_outstanding,
  (SELECT COUNT(*) FROM public.invoices WHERE payment_status = 'overdue') as overdue_invoices,
  (SELECT SUM(total_amount) FROM public.invoices WHERE payment_status IN ('sent', 'viewed', 'overdue')) as pending_payments;
